(function(){
  var BR = Java.loadClass("net.minecraft.core.registries.BuiltInRegistries");
  var RL = Java.loadClass("net.minecraft.resources.ResourceLocation");
  var TA = Java.loadClass("dev.emi.trinkets.api.TrinketsApi");
  var MCC = Java.loadClass("com.merlinkitsune.astral_dice.init.ModCompatibilityCheck");
  var FL = Java.loadClass("net.fabricmc.loader.api.FabricLoader");
  var out = {};
  var loader = FL.getInstance();
  out.trinketsLoaded = loader.isModLoaded("trinkets");
  out.accessoriesLoaded = loader.isModLoaded("accessories");
  out.aclLoaded = loader.isModLoaded("accessories_compat_layer");
  var tc = loader.getModContainer("trinkets");
  out.trinketsVersion = tc.isPresent() ? String(tc.get().getMetadata().getVersion().getFriendlyString()) : "";
  out.isTrinketsPresent = MCC.isTrinketsPresent();
  out.isAccessoriesPresent = MCC.isAccessoriesPresent();
  out.isAclPresent = MCC.isAccessoriesCompatLayerPresent();
  out.playerPresent = AutoJS.players()[0] != null;
  var it = BR.ITEM.iterator(), ast = 0, adapted = 0, diceTotal = 0, diceMiss = 0, miss = [];
  while (it.hasNext()) {
    var item = it.next();
    var rl = BR.ITEM.getKey(item);
    if (String(rl.getNamespace()) !== "astral_dice") { continue; }
    ast++;
    var s = String(TA.getTrinket(item));
    var hit = s.indexOf("Adapter[delegate=astral_dice:") >= 0;
    if (hit) { adapted++; }
    if (String(rl.getPath()).indexOf("_dice") >= 0) {
      diceTotal++;
      if (!hit) { diceMiss++; if (miss.length < 6) { miss.push(String(rl.getPath())); } }
    }
  }
  out.astralItems = ast;
  out.adapterCount = adapted;
  out.diceTotal = diceTotal;
  out.diceMissing = diceMiss;
  out.diceMissingIds = miss;
  out.diamondTrinket = String(TA.getTrinket(BR.ITEM.get(RL.parse("minecraft:diamond"))));
  out.diamondHasAdapter = out.diamondTrinket.indexOf("Adapter[delegate=astral_dice:") >= 0;
  return out;
})()
